-- Ukrainian choose_if + faq UPDATE — generated by gen_tool_choose_faq_ua_b3.py (batch 3/4)
BEGIN;
UPDATE tools SET choose_if = $t1ci$["✅ Вам потрібне просте покращення якості аудіо одним кліком без складного редактора", "✅ Adobe Podcast Enhance видаляє шум і покращує якість мікрофона безкоштовно", "✅ Ви вже у Creative Cloud і хочете інструмент що інтегрується з Premiere і Audition", "✅ Для швидкого покращення запису без вивчення повноцінного редактора"]$t1ci$::JSONB, faq = $t1fq$[{"q": "Descript vs Adobe Podcast — яка різниця?", "a": "Descript — повний редактор подкастів і відео з транскрибуванням і монтажем через текст. Adobe Podcast — простий онлайн-інструмент для покращення якості аудіо. Descript для повного виробництва; Adobe Podcast для швидкого покращення запису."}, {"q": "Descript безкоштовний?", "a": "Descript має безкоштовний план з обмеженнями (1 година транскрипції/міс). Creator від $24/міс. Adobe Podcast Enhance безкоштовний; повна Adobe Podcast у Creative Cloud ($54,99/міс)."}, {"q": "Adobe Podcast Enhance справді покращує якість?", "a": "Так. Adobe Podcast Enhance (Speech Enhancement) значно покращує якість аудіо знятого на звичайний мікрофон — зменшує шум, покращує чіткість. Безкоштовний і доступний без Adobe CC."}, {"q": "Descript для відеоподкастів — підходить?", "a": "Так. Descript відмінний для відеоподкастів: записує відео і аудіо, транскрибує, дозволяє монтаж через видалення слів у тексті. Популярний серед YouTubers і подкастерів що роблять відео-версії."}]$t1fq$::JSONB WHERE slug = 'adobe-podcast' AND lang = 'ua';
UPDATE tools SET choose_if = $t2ci$["✅ Вам потрібні автоматично адаптивні слайди що залишаються красивими при зміні контенту", "✅ Beautiful.ai Smart Templates автоматично адаптуються — додайте точку і слайд перебудується", "✅ Команди що роблять багато презентацій і потребують консистентного брендового дизайну", "✅ Beautiful.ai краще для традиційного слайд-формату без переходу на веб-презентації"]$t2ci$::JSONB, faq = $t2fq$[{"q": "Gamma vs Canva — що краще для презентацій?", "a": "Gamma генерує контент і дизайн з ШІ — менше ручної роботи. Canva дає більше дизайнерського контролю і шаблонів. Gamma для швидкого старту з ШІ; Canva для кастомного дизайну."}, {"q": "Beautiful.ai безкоштовний?", "a": "Beautiful.ai не має безкоштовного плану. Pro від $12/міс (щорічно). Gamma має безкоштовний план з 400 ШІ-кредитів; Plus від $10/міс."}, {"q": "Gamma може зберегти у PowerPoint?", "a": "Так. Gamma дозволяє експортувати презентацію у PDF і PowerPoint формат. Це корисно якщо отримувач потребує .pptx файлу."}, {"q": "Beautiful.ai для командних презентацій?", "a": "Так. Beautiful.ai має командні функції: Brand Kit для консистентного стилю, Workspace для спільного доступу і Team Plan. Ідеально для маркетингових команд що хочуть єдиний стиль."}]$t2fq$::JSONB WHERE slug = 'beautiful-ai' AND lang = 'ua';
UPDATE tools SET choose_if = $t3ci$["✅ Вам потрібно будувати повноцінний веб-застосунок з базою даних, логікою і бекендом без коду", "✅ Bubble — справжній no-code backend: користувачі, дані, дозволи, API-інтеграції", "✅ Ідеально для стартапів що будують SaaS, marketplace або складні веб-застосунки", "✅ Bubble дозволяє побудувати функціональний MVP без розробників"]$t3ci$::JSONB, faq = $t3fq$[{"q": "Bubble vs Webflow — що обрати для стартапу?", "a": "Bubble для стартапів що будують SaaS або застосунки з бізнес-логікою і базами даних. Webflow для маркетингових сайтів і агентств. Для MVP з функціональністю — Bubble; для красивого сайту — Webflow."}, {"q": "Bubble безкоштовний?", "a": "Bubble має безкоштовний план для розробки. Starter від $32/міс. Webflow безкоштовний для дизайну; Starter від $14/міс."}, {"q": "Чи можна масштабувати Bubble-застосунок?", "a": "Так, Bubble масштабується. Великі застосунки з тисячами користувачів працюють на Bubble. Для дуже великого навантаження потрібні вищі плани і оптимізація запитів до бази даних."}, {"q": "Webflow vs WordPress — яка різниця?", "a": "Webflow — візуальний конструктор сайтів з чистим кодом. WordPress — CMS з тисячами плагінів і більшою гнучкістю контенту. Webflow для дизайнерів що хочуть контроль; WordPress для контент-важких сайтів з великою екосистемою."}]$t3fq$::JSONB WHERE slug = 'bubble' AND lang = 'ua';
UPDATE tools SET choose_if = $t4ci$["✅ Вам потрібні прості відповіді «так/ні/суперечливо» на основі наукового консенсусу", "✅ Consensus наочно показує скільки досліджень підтримують або спростовують твердження", "✅ Простіший і доступніший ніж Elicit для студентів і нефахових дослідників", "✅ Consensus Meter — унікальна візуалізація наукового консенсусу одразу"]$t4ci$::JSONB, faq = $t4fq$[{"q": "Elicit vs Consensus — яка різниця?", "a": "Elicit — потужний інструмент для автоматизації систематичних оглядів і витягування даних. Consensus — простіший пошук наукового консенсусу з візуальним індикатором. Elicit для глибоких досліджень; Consensus для швидких перевірок тверджень."}, {"q": "Elicit безкоштовний?", "a": "Elicit має безкоштовний план з обмеженнями. Plus від $12/міс. Consensus безкоштовний з базовими функціями; Premium від $9,99/міс."}, {"q": "Elicit замінює PubMed?", "a": "Ні. PubMed — вичерпна база даних медичної літератури. Elicit використовує Semantic Scholar і інші бази як джерела. Для повного покриття медичної літератури PubMed незамінний; Elicit прискорює аналіз знайдених статей."}, {"q": "Consensus для медичних рішень — надійний?", "a": "Consensus допомагає зрозуміти загальні наукові тенденції але не замінює медичні консультації. Для клінічних рішень консультуйтесь з фахівцями і первинними джерелами."}]$t4fq$::JSONB WHERE slug = 'consensus' AND lang = 'ua';
UPDATE tools SET choose_if = $t5ci$["✅ Вам потрібен повноцінний відеоредактор де монтаж відбувається через редагування транскрипту", "✅ Descript записує, транскрибує, редагує відео і аудіо і публікує подкасти в одному місці", "✅ Overdub — клонування голосу для виправлення помилок без перезапису", "✅ Screen recording, субтитри і публікація в YouTube і подкаст-платформи прямо з Descript"]$t5ci$::JSONB, faq = $t5fq$[{"q": "Descript vs Adobe Podcast — яка різниця?", "a": "Descript — повний редактор подкастів і відео з транскрибуванням і монтажем через текст. Adobe Podcast — простий онлайн-інструмент для покращення якості аудіо. Descript для повного виробництва; Adobe Podcast для швидкого покращення запису."}, {"q": "Descript безкоштовний?", "a": "Descript має безкоштовний план з обмеженнями (1 година транскрипції/міс). Creator від $24/міс. Adobe Podcast Enhance безкоштовний; повна Adobe Podcast у Creative Cloud ($54,99/міс)."}, {"q": "Adobe Podcast Enhance справді покращує якість?", "a": "Так. Adobe Podcast Enhance (Speech Enhancement) значно покращує якість аудіо знятого на звичайний мікрофон — зменшує шум, покращує чіткість. Безкоштовний і доступний без Adobe CC."}, {"q": "Descript для відеоподкастів — підходить?", "a": "Так. Descript відмінний для відеоподкастів: записує відео і аудіо, транскрибує, дозволяє монтаж через видалення слів у тексті. Популярний серед YouTubers і подкастерів що роблять відео-версії."}]$t5fq$::JSONB WHERE slug = 'descript' AND lang = 'ua';
UPDATE tools SET choose_if = $t6ci$["✅ Вам потрібне ШІ-покращення у вивченні мов — пояснення помилок і розмовна практика", "✅ Duolingo Max додає ШІ-функції до Duolingo: Explain My Answer і Roleplay", "✅ Вивчення мов через гейміфікацію з ШІ-тьютором для розмовної практики", "✅ Duolingo — найбільша і найпопулярніша платформа вивчення мов у світі"]$t6ci$::JSONB, faq = $t6fq$[{"q": "Photomath безкоштовний?", "a": "Photomath безкоштовний з базовими розв'язаннями. Photomath Plus ($9,99/міс або $59,99/рік) дає покрокові пояснення і анімовані підказки. Duolingo безкоштовний; Max від $13,99/міс."}, {"q": "Photomath vs Wolfram Alpha — яка різниця?", "a": "Photomath спеціалізований на шкільній математиці з візуальними покроковими поясненнями. Wolfram Alpha потужніший для університетської математики, фізики і наукових розрахунків. Photomath для школярів; Wolfram Alpha для університету."}, {"q": "Duolingo Max — що нового порівняно зі звичайним Duolingo?", "a": "Duolingo Max додає Explain My Answer (ШІ пояснює чому відповідь правильна/неправильна) і Roleplay (розмовна практика з ШІ у сценаріях реального життя). Доступний для підписки Max."}, {"q": "Photomath допомагає з алгеброю?", "a": "Так. Photomath чудово вирішує алгебраїчні рівняння, нерівності, системи рівнянь і функції. Покрокові пояснення допомагають зрозуміти метод а не просто скопіювати відповідь."}]$t6fq$::JSONB WHERE slug = 'duolingo-max' AND lang = 'ua';
UPDATE tools SET choose_if = $t7ci$["✅ Вам потрібен реалістичний синтез мовлення і клонування голосу а не музика", "✅ ElevenLabs генерує природний голос для озвучення, подкастів, відео і застосунків", "✅ Клонування голосу: завантажте аудіо і ElevenLabs відтворить голос у будь-якому тексті", "✅ API для розробників що будують голосові застосунки і продукти"]$t7ci$::JSONB, faq = $t7fq$[{"q": "Suno vs ElevenLabs — яка різниця?", "a": "Suno генерує музику — пісні з вокалом і мелодією. ElevenLabs генерує мовлення — реалістичні голоси для озвучення. Різні продукти для різних потреб."}, {"q": "Suno безкоштовний?", "a": "Suno має безкоштовний план з 50 пісень/день (не комерційне використання). Pro $8/міс — 500 пісень і комерційні права. ElevenLabs безкоштовний з обмеженнями; платні від $5/міс."}, {"q": "Чи можна використовувати Suno комерційно?", "a": "Безкоштовний план — некомерційне використання. Pro і Premier плани дають комерційні права. Перевіряйте актуальні умови використання на сайті Suno."}, {"q": "ElevenLabs підтримує українську мову?", "a": "Так. ElevenLabs підтримує синтез мовлення та клонування голосу українською мовою. Якість висока для читання тексту і озвучення."}]$t7fq$::JSONB WHERE slug = 'elevenlabs' AND lang = 'ua';
UPDATE tools SET choose_if = $t8ci$["✅ Вам потрібен ШІ для систематичного огляду літератури і автоматизації дослідницьких завдань", "✅ Elicit знаходить і синтезує дані з наукових статей: розміри вибірки, методи, результати", "✅ Автоматичне витягування структурованих даних з тисяч публікацій для мета-аналізу", "✅ Ідеально для дослідників і аспірантів що пишуть систематичні огляди"]$t8ci$::JSONB, faq = $t8fq$[{"q": "Elicit vs Consensus — яка різниця?", "a": "Elicit — потужний інструмент для автоматизації систематичних оглядів і витягування даних. Consensus — простіший пошук наукового консенсусу з візуальним індикатором. Elicit для глибоких досліджень; Consensus для швидких перевірок тверджень."}, {"q": "Elicit безкоштовний?", "a": "Elicit має безкоштовний план з обмеженнями. Plus від $12/міс. Consensus безкоштовний з базовими функціями; Premium від $9,99/міс."}, {"q": "Elicit замінює PubMed?", "a": "Ні. PubMed — вичерпна база даних медичної літератури. Elicit використовує Semantic Scholar і інші бази як джерела. Для повного покриття медичної літератури PubMed незамінний; Elicit прискорює аналіз знайдених статей."}, {"q": "Consensus для медичних рішень — надійний?", "a": "Consensus допомагає зрозуміти загальні наукові тенденції але не замінює медичні консультації. Для клінічних рішень консультуйтесь з фахівцями і первинними джерелами."}]$t8fq$::JSONB WHERE slug = 'elicit' AND lang = 'ua';
UPDATE tools SET choose_if = $t9ci$["✅ Вам потрібна автоматична запис і аналіз зустрічей для продажів і CRM-інтеграцій", "✅ Fireflies.ai автоматично синхронізується з Salesforce, HubSpot і іншими CRM", "✅ Кращий пошук по всіх зустрічах — знайдіть будь-яку розмову за ключовими словами", "✅ Fireflies краще для команд що обробляють великі обсяги зустрічей і дзвінків"]$t9ci$::JSONB, faq = $t9fq$[{"q": "Otter.ai vs Fireflies.ai — яка різниця?", "a": "Otter.ai сильніший для транскрипції в реальному часі і особистої продуктивності. Fireflies.ai кращий для команд продажів з CRM-інтеграціями і пошуком по зустрічах. Otter для особистого використання; Fireflies для командного і продажового."}, {"q": "Otter.ai безкоштовний?", "a": "Otter.ai має безкоштовний план з 600 хвилин/міс транскрипції. Pro $16,99/міс. Fireflies.ai безкоштовний з обмеженнями; Pro $18/міс."}, {"q": "Ці інструменти записують без дозволу?", "a": "Обидва боти просять дозвіл перед входом у зустріч. Otter.ai і Fireflies.ai видимі для всіх учасників. Завжди повідомляйте учасників що зустріч записується — це вимога законодавства у більшості країн."}, {"q": "Fireflies.ai підтримує українську мову?", "a": "Fireflies.ai підтримує транскрипцію кількох мов але якість для української може бути нижчою ніж для англійської. Перевіряйте актуальні мовні можливості на сайті Fireflies."}]$t9fq$::JSONB WHERE slug = 'fireflies-ai' AND lang = 'ua';
UPDATE tools SET choose_if = $t10ci$["✅ Вам потрібен нативний мобільний застосунок для iOS і Android а не веб-застосунок", "✅ FlutterFlow будує Flutter-застосунки що публікуються в App Store і Google Play", "✅ Нативна продуктивність і кращий UX ніж веб-застосунки у мобільних браузерах", "✅ FlutterFlow генерує реальний Flutter-код який ви можете редагувати"]$t10ci$::JSONB, faq = $t10fq$[{"q": "FlutterFlow vs React Native — яка різниця?", "a": "FlutterFlow — visual builder для Flutter без написання коду. React Native — framework де потрібно писати JavaScript код. FlutterFlow швидший для старту без програмування; React Native гнучкіший для розробників."}, {"q": "FlutterFlow безкоштовний?", "a": "FlutterFlow має безкоштовний план без публікації. Standard від $30/міс. Bubble безкоштовний для розробки; Starter від $32/міс."}, {"q": "FlutterFlow для iOS — підходить?", "a": "Так. FlutterFlow будує нативні iOS-застосунки через Flutter. Вам потрібен Mac і Apple Developer акаунт ($99/рік) для публікації в App Store."}, {"q": "Bubble для мобільних застосунків?", "a": "Bubble будує веб-застосунки що працюють у мобільних браузерах або як PWA. Для справжнього нативного мобільного застосунку з App Store — FlutterFlow, Adalo або кодування на React Native/Flutter."}]$t10fq$::JSONB WHERE slug = 'flutterflow' AND lang = 'ua';
UPDATE tools SET choose_if = $t11ci$["✅ Вам потрібно швидко генерувати красивий лендінг або сайт з ШІ-підказки", "✅ Framer AI генерує повний сайт з описом за секунди — набагато швидше ніж Webflow", "✅ Чудові анімації і сучасний дизайн з коробки без глибоких знань Webflow", "✅ Framer простіший для дизайнерів знайомих з Figma — схожий інтерфейс"]$t11ci$::JSONB, faq = $t11fq$[{"q": "Webflow vs Squarespace — яка різниця?", "a": "Webflow дає більше контролю над дизайном і кодом. Squarespace простіший і краще для новачків. Webflow для дизайнерів і агентств; Squarespace для малого бізнесу без технічних навичок."}, {"q": "Webflow безкоштовний?", "a": "Webflow безкоштовний для дизайну і розробки. Публікація від $14/міс. Framer безкоштовний для тестування; Mini від $5/міс."}, {"q": "Framer AI vs Webflow — що швидше?", "a": "Framer AI значно швидше для генерації початкового сайту з ШІ. Webflow швидше для складного CMS-сайту для досвідченого користувача. Framer для швидкого старту; Webflow для контрольованого складного проєкту."}, {"q": "Webflow для агентств?", "a": "Webflow дуже популярний серед веб-агентств. Клієнтський Editor дозволяє клієнтам редагувати контент самостійно. Workspace плани дають управління кількома клієнтськими сайтами."}]$t11fq$::JSONB WHERE slug = 'framer-ai' AND lang = 'ua';
UPDATE tools SET choose_if = $t12ci$["✅ Вам потрібно швидко створити гарну презентацію або веб-сторінку з ШІ-підказки", "✅ Gamma генерує повноцінні презентації з дизайном, структурою і контентом за секунди", "✅ Gamma-презентації — це інтерактивні веб-посилання а не PowerPoint-файли", "✅ Ідеально для пітч-деків, звітів і навчальних матеріалів без дизайнерських навичок"]$t12ci$::JSONB, faq = $t12fq$[{"q": "Gamma vs PowerPoint — в чому різниця?", "a": "Gamma генерує презентації з ШІ і публікує їх як веб-сторінки. PowerPoint — традиційний офлайн-редактор з повним контролем над дизайном. Gamma для швидкого старту; PowerPoint для точного контролю."}, {"q": "Gamma безкоштовний?", "a": "Gamma має безкоштовний план з 400 ШІ-кредитів. Plus від $10/міс. Notion безкоштовний для особистого використання; Teams від $16/міс/учасника."}, {"q": "Notion AI може робити презентації?", "a": "Notion AI може писати контент для презентацій і структурувати інформацію. Але він не генерує готові слайди. Для презентацій потрібен Gamma, Canva або PowerPoint."}, {"q": "Gamma для бізнес-пітчів — підходить?", "a": "Так. Gamma популярний для пітч-деків, пропозицій і клієнтських презентацій. ШІ-генерація швидко дає структуру і дизайн. Для важливих інвестиційних пітчів рекомендується також ручне доопрацювання."}]$t12fq$::JSONB WHERE slug = 'gamma' AND lang = 'ua';
UPDATE tools SET choose_if = $t13ci$["✅ Вам потрібно швидко перетворити Google Sheets або Airtable у мобільний застосунок", "✅ Glide — найпростіший спосіб створити застосунок з існуючих даних без дизайну з нуля", "✅ Ідеально для внутрішніх інструментів, каталогів і простих бізнес-застосунків", "✅ Glide запускається за годину — значно швидше ніж повне no-code рішення у Bubble"]$t13ci$::JSONB, faq = $t13fq$[{"q": "Glide vs Adalo — яка різниця?", "a": "Glide простіший і будує з існуючих даних (Sheets, Airtable). Adalo більш гнучкий для кастомних мобільних застосунків з власною базою даних. Glide для швидкого старту з даними; Adalo для нативних мобільних застосунків."}, {"q": "Glide безкоштовний?", "a": "Glide має безкоштовний план для тестування. Starter від $49/міс. Bubble має безкоштовний план; Starter від $32/міс."}, {"q": "Glide підходить для бізнес-застосунків?", "a": "Так. Glide популярний для корпоративних внутрішніх інструментів: каталоги продуктів, системи управління, CRM-подібні рішення. Простий у впровадженні для нетехнічних команд."}, {"q": "Bubble vs Glide — яка різниця?", "a": "Bubble — потужна no-code платформа для складних застосунків. Glide — простіший конструктор що перетворює таблиці у застосунки. Bubble для SaaS і складних продуктів; Glide для внутрішніх інструментів з існуючими даними."}]$t13fq$::JSONB WHERE slug = 'glide' AND lang = 'ua';
UPDATE tools SET choose_if = $t14ci$["✅ Вам потрібне середовище для аналітиків і data scientists з Python, SQL і ШІ в одному місці", "✅ Hex поєднує notebook-стиль роботи з красивими дашбордами для публікації результатів", "✅ Hex Magic AI генерує SQL і Python код з природньомовних запитів", "✅ Ідеально для технічних аналітичних команд що хочуть і гнучкість ноутбуків і красиві звіти"]$t14ci$::JSONB, faq = $t14fq$[{"q": "Hex vs Jupyter Notebook — яка різниця?", "a": "Jupyter — локальний відкритий ноутбук для розробки. Hex — хмарна платформа де ноутбуки перетворюються на живі застосунки і дашборди для ділення з командою. Hex значно зручніший для командної роботи."}, {"q": "Hex безкоштовний?", "a": "Hex має безкоштовний план для індивідуального використання. Team від $24/місяць/користувач. Looker Studio повністю безкоштовний."}, {"q": "Hex підтримує Python і SQL?", "a": "Так. Hex підтримує Python, SQL і R в одному ноутбуці. Ви можете змішувати клітинки SQL і Python у одному документі і результати автоматично передаються між ними."}, {"q": "Looker Studio vs Tableau — що обрати?", "a": "Looker Studio безкоштовний і простіший для Google-екосистеми. Tableau потужніший для складної аналітики і enterprise але дорогий. Для старту і Google-даних — Looker Studio; для серйозної enterprise аналітики — Tableau."}]$t14fq$::JSONB WHERE slug = 'hex' AND lang = 'ua';
UPDATE tools SET choose_if = $t15ci$["✅ Вам потрібен інструмент для аналізу великих обсягів PDF для корпоративного та академічного використання", "✅ Humata обробляє більше файлів одночасно у одному робочому просторі", "✅ Humata дозволяє ставити запитання до кількох документів одночасно", "✅ Кращі можливості для команд що співпрацюють над аналізом документів"]$t15ci$::JSONB, faq = $t15fq$[{"q": "NotebookLM vs Humata — яка різниця?", "a": "NotebookLM від Google безкоштовний з унікальним Audio Overview. Humata платний з кращою обробкою великих обсягів документів. Для особистого використання — NotebookLM; для корпоративного аналізу документів — Humata."}, {"q": "NotebookLM безкоштовний?", "a": "Так. NotebookLM повністю безкоштовний від Google. NotebookLM Plus доступний через Google One AI Premium ($19,99/міс). Humata має безкоштовний план з обмеженнями; платні від $9/міс."}, {"q": "Що таке Audio Overview у NotebookLM?", "a": "Audio Overview — фіча NotebookLM що генерує природню подкаст-дискусію двох ШІ-ведучих на основі ваших документів. Ідеально для засвоєння матеріалу через прослуховування замість читання."}, {"q": "NotebookLM може аналізувати відео?", "a": "NotebookLM може аналізувати YouTube відео через посилання. Він транскрибує і аналізує контент відео. Обмеження — лише публічні YouTube відео; власні відео не підтримуються безпосередньо."}]$t15fq$::JSONB WHERE slug = 'humata' AND lang = 'ua';
UPDATE tools SET choose_if = $t16ci$["✅ Вам потрібен ШІ-аналітик що відповідає на питання про ваші дані природньою мовою", "✅ Julius AI аналізує CSV, Excel і бази даних — просто завантажте і питайте", "✅ Генерує візуалізації, знаходить тренди і пояснює результати людською мовою", "✅ Ідеально для нетехнічних користувачів без SQL і знань BI-платформ"]$t16ci$::JSONB, faq = $t16fq$[{"q": "Julius AI vs ChatGPT для аналізу даних — яка різниця?", "a": "Julius AI спеціалізований для даних: завантажте файл і отримуйте аналіз. ChatGPT більш загальний і має обмежені можливості роботи з файлами. Для аналізу даних Julius AI зручніший; для загальних задач — ChatGPT."}, {"q": "Julius AI безкоштовний?", "a": "Julius AI має безкоштовний план з обмеженим числом повідомлень. Pro від $20/міс. Looker Studio повністю безкоштовний."}, {"q": "Julius AI може писати SQL?", "a": "Так. Julius AI може генерувати SQL-запити і виконувати їх проти ваших даних. Він також пояснює що робить SQL і інтерпретує результати."}, {"q": "Looker Studio для малого бізнесу?", "a": "Так. Looker Studio ідеальний для малого бізнесу — безкоштовний і відмінно інтегрується з Google Ads і Google Analytics. Для команд без BI-спеціаліста це найпростіший старт з дашбордами."}]$t16fq$::JSONB WHERE slug = 'julius-ai' AND lang = 'ua';
UPDATE tools SET choose_if = $t17ci$["✅ Вам потрібен ШІ-тьютор що навчає через запитання а не просто дає відповіді", "✅ Khanmigo направляє до розуміння — не розв'язує задачу замість учня", "✅ Охоплює всі предмети Khan Academy: математику, науки, програмування, історію", "✅ Розмовний ШІ-тьютор що адаптується до рівня і потреб кожного учня"]$t17ci$::JSONB, faq = $t17fq$[{"q": "Khanmigo безкоштовний?", "a": "Khanmigo доступний за $44/рік для учнів або безкоштовно в деяких американських школах через партнерства Khan Academy. Photomath безкоштовний для базових функцій; Plus $9,99/міс."}, {"q": "Khanmigo для дорослих — підходить?", "a": "Так. Khanmigo підходить для будь-кого хто вчиться через Khan Academy — від школярів до дорослих що вивчають нові теми. ШІ-тьютор адаптується до рівня користувача."}, {"q": "Photomath вирішує задачі на слова?", "a": "Так. Photomath може вирішувати текстові задачі — сфотографуйте умову і він розв'яже. Але задачі на слова потребують правильного розпізнавання тексту і іноді менш надійні ніж символьні рівняння."}, {"q": "Khanmigo vs ChatGPT для навчання?", "a": "Khanmigo спеціально оптимізований для навчання — направляє учня до відповіді через запитання. ChatGPT відразу дає відповідь. Для реального навчання і розуміння — Khanmigo; для швидкої перевірки — ChatGPT."}]$t17fq$::JSONB WHERE slug = 'khanmigo' AND lang = 'ua';
UPDATE tools SET choose_if = $t18ci$["✅ Вам потрібний безкоштовний інструмент BI з відмінною інтеграцією Google (GA4, BigQuery, Sheets)", "✅ Looker Studio (колишній Google Data Studio) безкоштовний для необмеженої кількості звітів", "✅ Ідеально для маркетингових і SEO-дашбордів що тягнуть дані з Google Analytics", "✅ Простіший старт — ніяких платних ліцензій і установки ПЗ"]$t18ci$::JSONB, faq = $t18fq$[{"q": "Looker Studio vs Power BI — яка різниця?", "a": "Looker Studio безкоштовний і відмінний для Google-екосистеми. Power BI потужніший для Microsoft-середовищ і enterprise аналітики. Обидва мають ШІ-функції. Для Google — Looker Studio; для Microsoft — Power BI."}, {"q": "Looker Studio безкоштовний?", "a": "Так. Looker Studio (раніше Data Studio) повністю безкоштовний. Tableau починається від $75/користувач/міс (Creator). Power BI безкоштовний для базового використання; Premium від $10/користувач/міс."}, {"q": "Tableau AI що вміє?", "a": "Tableau AI (Tableau Einstein) дозволяє ставити запитання до ваших даних природньою мовою і отримувати візуалізації. Також прогнозування трендів і виявлення аномалій автоматично."}, {"q": "Looker Studio для e-commerce?", "a": "Так. Looker Studio популярний для e-commerce аналітики: GA4, Google Ads, Search Console. Є безліч готових шаблонів для e-commerce дашбордів. Для інтеграції з Facebook Ads або іншими платформами потрібні сторонні конектори."}]$t18fq$::JSONB WHERE slug = 'looker-studio' AND lang = 'ua';
UPDATE tools SET choose_if = $t19ci$["✅ Вам потрібно генерувати веб-застосунок з описом природньою мовою за хвилини", "✅ Lovable використовує ШІ для генерації повного коду React-застосунку включно з UI і логікою", "✅ Швидший старт — Lovable від ідеї до працюючого застосунку за годину", "✅ Lovable генерує реальний код що можна редагувати — ви не locked-in у no-code систему"]$t19ci$::JSONB, faq = $t19fq$[{"q": "Lovable vs Bolt.new — яка різниця?", "a": "Обидва ШІ-генератори застосунків. Lovable більш орієнтований на повноцінні веб-застосунки з Supabase-інтеграцією. Bolt.new також сильний для фронтенду. Обидва генерують реальний код."}, {"q": "Lovable безкоштовний?", "a": "Lovable має безкоштовний план з обмеженнями. Starter від $20/міс. Bubble має безкоштовний план; Starter від $32/міс."}, {"q": "Lovable генерує реальний код?", "a": "Так. Lovable генерує справжній React-код що можна завантажити, редагувати і розгортати незалежно. Це велика перевага над no-code платформами де ви прив'язані до їхньої екосистеми."}, {"q": "Bubble без коду — чи реально це?", "a": "Так. Bubble — справжня no-code платформа де ви будуєте все через візуальний редактор без написання коду. Але для складних сценаріїв потрібне розуміння логіки і баз даних."}]$t19fq$::JSONB WHERE slug = 'lovable' AND lang = 'ua';
UPDATE tools SET choose_if = $t20ci$["✅ Вам потрібна потужна автоматизація зі складною логікою, трансформаціями і розгалуженнями", "✅ Make значно дешевший за Zapier при тих самих обсягах — до 10x економії", "✅ Візуальний builder Make показує дані і дозволяє складні сценарії з ітераціями", "✅ Більш гнучкий для розробників і технічних команд що потребують нестандартних рішень"]$t20ci$::JSONB, faq = $t20fq$[{"q": "Zapier vs Make — що краще?", "a": "Zapier простіший і має більше готових конекторів. Make потужніший і набагато дешевший для складних сценаріїв. Для нетехнічних команд — Zapier; для технічних команд з бюджетними обмеженнями — Make."}, {"q": "Zapier безкоштовний?", "a": "Zapier має безкоштовний план з 100 завдань/міс і однокроковими Zaps. Платні плани від $19,99/міс. Make безкоштовний до 1000 операцій/міс; платні від $9/міс."}, {"q": "Zapier AI що він вміє?", "a": "Zapier AI включає AI Actions (природньомовні кроки у Zap), AI Chatbot (побудова ботів без коду) і Zapier Canvas (візуальне планування автоматизацій з ШІ). Дозволяє додавати ШІ-логіку у традиційні автоматизації."}, {"q": "Make vs n8n — яка різниця?", "a": "Make hosted-сервіс з красивим інтерфейсом. n8n відкритий і безкоштовний при self-hosting. Make для команд що хочуть хмарне рішення; n8n для технічних команд з контролем над даними."}]$t20fq$::JSONB WHERE slug = 'make' AND lang = 'ua';
UPDATE tools SET choose_if = $t21ci$["✅ Вам потрібен ШІ-планувальник що автоматично будує ваш ідеальний розклад дня з завдань", "✅ Motion пріоритизує завдання, дедлайни і зустрічі та перепланує якщо щось змінюється", "✅ Управління проєктами і завданнями вбудоване — не потрібен окремий task manager", "✅ Ідеально для зайнятих людей що хочуть делегувати планування ШІ"]$t21ci$::JSONB, faq = $t21fq$[{"q": "Motion vs Reclaim.ai — яка різниця?", "a": "Motion повністю перепланує ваш день навколо завдань і дедлайнів. Reclaim.ai захищає існуючий час і додає розумні звички у ваш Google Calendar. Motion для тих хто хоче повну автоматизацію планування; Reclaim для захисту часу."}, {"q": "Motion безкоштовний?", "a": "Motion не має безкоштовного плану. Individual від $34/міс (щомісячно) або $19/міс (щорічно). Reclaim.ai має безкоштовний план; Starter від $10/міс."}, {"q": "Motion vs Todoist — яка різниця?", "a": "Todoist — традиційний task manager де ви самі вирішуєте коли робити завдання. Motion автоматично планує коли виконати кожне завдання виходячи з дедлайнів і доступного часу. Motion для автоматичного планування; Todoist для структурованих списків."}, {"q": "Reclaim.ai працює з Outlook?", "a": "Reclaim.ai оптимізований для Google Calendar. Підтримка Outlook обмежена. Якщо ваша компанія на Microsoft 365 — перевірте актуальну сумісність на сайті Reclaim.ai."}]$t21fq$::JSONB WHERE slug = 'motion' AND lang = 'ua';
UPDATE tools SET choose_if = $t22ci$["✅ Вам потрібен ШІ що аналізує ваші власні документи: PDF, нотатки, статті", "✅ NotebookLM від Google безкоштовний і глибоко аналізує завантажені джерела", "✅ Audio Overview — NotebookLM генерує подкаст-дискусію на основі ваших документів", "✅ Ідеально для студентів, дослідників і всіх що хочуть краще зрозуміти свої матеріали"]$t22ci$::JSONB, faq = $t22fq$[{"q": "Perplexity vs Google — яка різниця?", "a": "Perplexity синтезує відповідь з кількох джерел і дає цитати. Google показує список посилань де ви самі шукаєте відповідь. Perplexity швидший для прямих відповідей; Google повніший для глибокого пошуку."}, {"q": "Perplexity безкоштовний?", "a": "Perplexity безкоштовний з базовими функціями. Pro $20/міс з розширеними моделями і більше пошуків. NotebookLM повністю безкоштовний від Google."}, {"q": "NotebookLM може читати мої PDF?", "a": "Так. NotebookLM аналізує PDF, Google Docs, веб-сторінки і YouTube відео. Він відповідає на запитання виключно на основі ваших джерел і завжди вказує звідки взята інформація."}, {"q": "Perplexity для академічних досліджень?", "a": "Perplexity непогано для попередніх досліджень але не завжди посилається на рецензовані джерела. Для академічних досліджень Consensus, Elicit або Semantic Scholar з верифікованими науковими публікаціями надійніші."}]$t22fq$::JSONB WHERE slug = 'notebooklm' AND lang = 'ua';
UPDATE tools SET choose_if = $t23ci$["✅ Ваша команда вже використовує Notion і ви хочете ШІ прямо у робочому просторі", "✅ Notion AI пише, резюмує, перекладає і редагує прямо у ваших нотатках і документах", "✅ Ідеально для команд що управляють проєктами і документацією в Notion", "✅ Notion AI Plus ($16/міс/учасника) інтегрований без додаткових налаштувань"]$t23ci$::JSONB, faq = $t23fq$[{"q": "Notion AI vs ChatGPT — що краще для нотаток?", "a": "Notion AI кращий якщо ви вже у Notion: він знає ваші документи і може з ними працювати. ChatGPT потужніший загально але не має доступу до ваших нотаток. Для Notion-команд — Notion AI; для загального ШІ — ChatGPT."}, {"q": "Notion AI безкоштовний?", "a": "Notion AI Plus — $16/міс/учасника (щорічно) або $20/міс щомісячно, додатково до базового Notion. Zapier має безкоштовний план; AI-функції у платних планах від $19,99/міс."}, {"q": "Zapier AI що це таке?", "a": "Zapier AI — набір ШІ-функцій у Zapier включно з AI Actions (природньомовні кроки у Zap), AI Chatbot (побудова чат-ботів) і Canvas (візуальний будівник автоматизацій з ШІ). Дозволяє будувати складніші автоматизації."}, {"q": "Notion AI може писати код?", "a": "Notion AI може писати базовий код і SQL. Але для серйозного кодування Cursor, GitHub Copilot або Claude Code значно потужніші. Notion AI краще для текстових завдань ніж для кодування."}]$t23fq$::JSONB WHERE slug = 'notion-ai' AND lang = 'ua';
UPDATE tools SET choose_if = $t24ci$["✅ Вам потрібна транскрипція зустрічей у реальному часі з редагуванням і нотатками", "✅ Otter.ai відображає транскрипцію прямо під час розмови — учасники бачать текст одночасно", "✅ Otter.ai Assistant приєднується до Zoom, Teams і Google Meet і веде нотатки автоматично", "✅ Особисте використання і невеликі команди — Otter.ai простіший і інтуїтивніший"]$t24ci$::JSONB, faq = $t24fq$[{"q": "Otter.ai vs Fireflies.ai — яка різниця?", "a": "Otter.ai сильніший для транскрипції в реальному часі і особистої продуктивності. Fireflies.ai кращий для команд продажів з CRM-інтеграціями і пошуком по зустрічах. Otter для особистого використання; Fireflies для командного і продажового."}, {"q": "Otter.ai безкоштовний?", "a": "Otter.ai має безкоштовний план з 600 хвилин/міс транскрипції. Pro $16,99/міс. Fireflies.ai безкоштовний з обмеженнями; Pro $18/міс."}, {"q": "Ці інструменти записують без дозволу?", "a": "Обидва боти просять дозвіл перед входом у зустріч. Otter.ai і Fireflies.ai видимі для всіх учасників. Завжди повідомляйте учасників що зустріч записується — це вимога законодавства у більшості країн."}, {"q": "Fireflies.ai підтримує українську мову?", "a": "Fireflies.ai підтримує транскрипцію кількох мов але якість для української може бути нижчою ніж для англійської. Перевіряйте актуальні мовні можливості на сайті Fireflies."}]$t24fq$::JSONB WHERE slug = 'otter-ai' AND lang = 'ua';
UPDATE tools SET choose_if = $t25ci$["✅ Вам потрібна пошукова система з ШІ для актуальних відповідей з посиланнями на джерела", "✅ Perplexity знаходить і синтезує інформацію з інтернету в реальному часі", "✅ Ідеально для швидких досліджень, перевірки фактів і актуальних новин з цитатами", "✅ Perplexity Pro ($20/міс) дає доступ до GPT-4o, Claude і Gemini в одному місці"]$t25ci$::JSONB, faq = $t25fq$[{"q": "Perplexity vs Google — яка різниця?", "a": "Perplexity синтезує відповідь з кількох джерел і дає цитати. Google показує список посилань де ви самі шукаєте відповідь. Perplexity швидший для прямих відповідей; Google повніший для глибокого пошуку."}, {"q": "Perplexity безкоштовний?", "a": "Perplexity безкоштовний з базовими функціями. Pro $20/міс з розширеними моделями і більше пошуків. NotebookLM повністю безкоштовний від Google."}, {"q": "NotebookLM може читати мої PDF?", "a": "Так. NotebookLM аналізує PDF, Google Docs, веб-сторінки і YouTube відео. Він відповідає на запитання виключно на основі ваших джерел і завжди вказує звідки взята інформація."}, {"q": "Perplexity для академічних досліджень?", "a": "Perplexity непогано для попередніх досліджень але не завжди посилається на рецензовані джерела. Для академічних досліджень Consensus, Elicit або Semantic Scholar з верифікованими науковими публікаціями надійніші."}]$t25fq$::JSONB WHERE slug = 'perplexity' AND lang = 'ua';
UPDATE tools SET choose_if = $t26ci$["✅ Вам потрібно вирішувати математичні задачі з поясненнями покрокового розв'язання", "✅ Photomath сканує рукописні або друковані задачі камерою і розв'язує їх із поясненнями", "✅ Ідеально для учнів і студентів що хочуть зрозуміти математику а не просто відповідь", "✅ Охоплює від базової арифметики до вищої математики, геометрії і тригонометрії"]$t26ci$::JSONB, faq = $t26fq$[{"q": "Photomath безкоштовний?", "a": "Photomath безкоштовний з базовими розв'язаннями. Photomath Plus ($9,99/міс або $59,99/рік) дає покрокові пояснення і анімовані підказки. Duolingo безкоштовний; Max від $13,99/міс."}, {"q": "Photomath vs Wolfram Alpha — яка різниця?", "a": "Photomath спеціалізований на шкільній математиці з візуальними покроковими поясненнями. Wolfram Alpha потужніший для університетської математики, фізики і наукових розрахунків. Photomath для школярів; Wolfram Alpha для університету."}, {"q": "Duolingo Max — що нового порівняно зі звичайним Duolingo?", "a": "Duolingo Max додає Explain My Answer (ШІ пояснює чому відповідь правильна/неправильна) і Roleplay (розмовна практика з ШІ у сценаріях реального життя). Доступний для підписки Max."}, {"q": "Photomath допомагає з алгеброю?", "a": "Так. Photomath чудово вирішує алгебраїчні рівняння, нерівності, системи рівнянь і функції. Покрокові пояснення допомагають зрозуміти метод а не просто скопіювати відповідь."}]$t26fq$::JSONB WHERE slug = 'photomath' AND lang = 'ua';
UPDATE tools SET choose_if = $t27ci$["✅ Ви будуєте інвестиційні пітч-деки і продажові презентації з командою", "✅ Pitch Analytics показує хто відкрив ваш deck і скільки часу провів на кожному слайді", "✅ Pitch має сильніші командні функції: live-редагування, коментарі і версії", "✅ Кращі шаблони спеціально для стартапів і бізнес-пітчів"]$t27ci$::JSONB, faq = $t27fq$[{"q": "Pitch vs PowerPoint — яка різниця?", "a": "Pitch — сучасний хмарний інструмент презентацій з командною роботою і аналітикою. PowerPoint — класичний офлайн-редактор з повним контролем. Pitch для командних онлайн-презентацій; PowerPoint для максимальної сумісності."}, {"q": "Pitch безкоштовний?", "a": "Pitch має безкоштовний план для до 3 членів команди. Pro від $8/член/міс. Gamma має безкоштовний план; Plus від $10/міс."}, {"q": "Gamma для investor deck?", "a": "Gamma може генерувати investor deck з підказки. Але для реальних інвестиційних пітчів Pitch має кращі шаблони і аналітику для відстеження хто читав ваш deck. Gamma для черновика; Pitch для фінального пітчу."}, {"q": "Pitch vs Canva для презентацій?", "a": "Pitch спеціалізований для бізнес-презентацій з командою і аналітикою. Canva більш загальний з тисячами шаблонів. Pitch для командних бізнес-пітчів; Canva для різноманітних дизайн-потреб."}]$t27fq$::JSONB WHERE slug = 'pitch' AND lang = 'ua';
UPDATE tools SET choose_if = $t28ci$["✅ Вам потрібен ШІ що захищає ваш час у Google Calendar від нескінченних зустрічей", "✅ Reclaim.ai автоматично блокує час для звичок, фокусного часу і пріоритетних завдань", "✅ Smart Meetings — знаходить оптимальний час для зустрічей для всіх учасників", "✅ Reclaim дешевший і простіший для захисту часу без повного перепланування"]$t28ci$::JSONB, faq = $t28fq$[{"q": "Motion vs Reclaim.ai — яка різниця?", "a": "Motion повністю перепланує ваш день навколо завдань і дедлайнів. Reclaim.ai захищає існуючий час і додає розумні звички у ваш Google Calendar. Motion для тих хто хоче повну автоматизацію планування; Reclaim для захисту часу."}, {"q": "Motion безкоштовний?", "a": "Motion не має безкоштовного плану. Individual від $34/міс (щомісячно) або $19/міс (щорічно). Reclaim.ai має безкоштовний план; Starter від $10/міс."}, {"q": "Motion vs Todoist — яка різниця?", "a": "Todoist — традиційний task manager де ви самі вирішуєте коли робити завдання. Motion автоматично планує коли виконати кожне завдання виходячи з дедлайнів і доступного часу. Motion для автоматичного планування; Todoist для структурованих списків."}, {"q": "Reclaim.ai працює з Outlook?", "a": "Reclaim.ai оптимізований для Google Calendar. Підтримка Outlook обмежена. Якщо ваша компанія на Microsoft 365 — перевірте актуальну сумісність на сайті Reclaim.ai."}]$t28fq$::JSONB WHERE slug = 'reclaim-ai' AND lang = 'ua';
UPDATE tools SET choose_if = $t29ci$["✅ Вам потрібно швидко будувати внутрішні інструменти: адмін-панелі, CRUD-застосунки, дашборди з діями", "✅ Retool не просто показує дані — дозволяє редагувати, запускати дії і управляти через UI", "✅ Retool AI дозволяє будувати ШІ-функції у внутрішніх інструментах: чат-боти, GPT-форми", "✅ Ідеально для операційних команд що потребують інтерактивних а не лише аналітичних інструментів"]$t29ci$::JSONB, faq = $t29fq$[{"q": "Retool vs AppSmith — яка різниця?", "a": "Обидва low-code конструктори внутрішніх інструментів. AppSmith відкритий і безкоштовний. Retool має більше компонентів і кращу підтримку але платний. Для open-source і self-hosted — AppSmith; для швидшого старту з підтримкою — Retool."}, {"q": "Retool безкоштовний?", "a": "Retool має безкоштовний план для 5 користувачів. Team від $10/користувач/міс. Looker Studio повністю безкоштовний."}, {"q": "Retool AI що вміє?", "a": "Retool AI дозволяє додавати ШІ-функції у внутрішні інструменти: GPT-запити, векторний пошук, ШІ-класифікацію. Ви можете будувати внутрішні чат-боти і ШІ-інтерфейси без написання бекенд-коду."}, {"q": "Looker Studio vs Power BI для маркетингу?", "a": "Looker Studio кращий для маркетологів у Google-екосистемі — безкоштовний і відмінно інтегрується з GA4 і Google Ads. Power BI кращий якщо компанія на Microsoft 365. Для Google-маркетингу — Looker Studio однозначно."}]$t29fq$::JSONB WHERE slug = 'retool-ai' AND lang = 'ua';
UPDATE tools SET choose_if = $t30ci$["✅ Вам потрібна розумна таблиця що поєднує Excel-знайомий інтерфейс з живими API-даними", "✅ Rows підключається до Stripe, Google Analytics, LinkedIn і тягне дані автоматично", "✅ ШІ-аналітик у Rows відповідає на запитання і будує формули природньою мовою", "✅ Краще для бізнес-аналітиків і операційних команд без технічних навичок"]$t30ci$::JSONB, faq = $t30fq$[{"q": "Rows vs Google Sheets — яка різниця?", "a": "Google Sheets — традиційна таблиця. Rows — розумна таблиця з вбудованими live-інтеграціями до Stripe, GA4, CRM та ін. і ШІ-асистентом. Rows ідеальний для автоматичних бізнес-звітів без щоденного оновлення вручну."}, {"q": "Rows безкоштовний?", "a": "Rows має безкоштовний план з обмеженнями. Plus від $59/міс. Hex має безкоштовний план; Team від $24/місяць/користувач."}, {"q": "Rows підходить для фінансової звітності?", "a": "Так. Rows добре підходить для фінансових дашбордів: підключається до Stripe, QuickBooks, банківських API і показує дохід, витрати і ключові метрики автоматично. Ідеально для стартапів і малого бізнесу."}, {"q": "Hex vs Databricks — яка різниця?", "a": "Databricks — enterprise-платформа для великих даних і ML в хмарі. Hex — легша аналітична платформа для команд аналітиків. Databricks для data engineering і великих ML-пайплайнів; Hex для аналітичних звітів і BI."}]$t30fq$::JSONB WHERE slug = 'rows' AND lang = 'ua';
UPDATE tools SET choose_if = $t31ci$["✅ Вам потрібно знати як стаття цитується — підтверджують її наступні дослідження чи спростовують", "✅ Scite показує Citation Statements: цитує підтримуючи, суперечачи чи нейтрально", "✅ Smart Citations допомагають оцінити достовірність статті через аналіз контексту цитувань", "✅ Scite Assistant — ШІ-чат що відповідає на наукові запитання з посиланнями"]$t31ci$::JSONB, faq = $t31fq$[{"q": "Scite vs Google Scholar — яка різниця?", "a": "Google Scholar показує хто цитує статтю. Scite показує як цитує — підтримуючи, суперечачи чи нейтрально. Scite дає якісний аналіз цитувань; Google Scholar ширше покриття."}, {"q": "Scite безкоштовний?", "a": "Scite має обмежений безкоштовний доступ. Підписка від $20/міс або $144/рік. Semantic Scholar повністю безкоштовний."}, {"q": "Що таке Semantic Scholar?", "a": "Semantic Scholar — безкоштовна пошукова система наукових публікацій від Allen Institute for AI. Охоплює понад 220 мільйонів статей і використовує ШІ для аналізу важливості і зв'язків між публікаціями."}, {"q": "Scite для медичних досліджень?", "a": "Так. Scite дуже корисний для медичних досліджень — розуміти чи підтверджені результати клінічних досліджень наступними роботами. Дозволяє оцінити надійність доказової бази."}]$t31fq$::JSONB WHERE slug = 'scite' AND lang = 'ua';
UPDATE tools SET choose_if = $t32ci$["✅ Вам потрібна безкоштовна потужна пошукова система по 220 млн наукових публікацій", "✅ Semantic Scholar безкоштовний з розширеними фільтрами і метриками впливовості", "✅ Ідеально для широкого пошуку літератури без платної підписки", "✅ API Semantic Scholar для розробників що будують наукові застосунки"]$t32ci$::JSONB, faq = $t32fq$[{"q": "Scite vs Google Scholar — яка різниця?", "a": "Google Scholar показує хто цитує статтю. Scite показує як цитує — підтримуючи, суперечачи чи нейтрально. Scite дає якісний аналіз цитувань; Google Scholar ширше покриття."}, {"q": "Scite безкоштовний?", "a": "Scite має обмежений безкоштовний доступ. Підписка від $20/міс або $144/рік. Semantic Scholar повністю безкоштовний."}, {"q": "Що таке Semantic Scholar?", "a": "Semantic Scholar — безкоштовна пошукова система наукових публікацій від Allen Institute for AI. Охоплює понад 220 мільйонів статей і використовує ШІ для аналізу важливості і зв'язків між публікаціями."}, {"q": "Scite для медичних досліджень?", "a": "Так. Scite дуже корисний для медичних досліджень — розуміти чи підтверджені результати клінічних досліджень наступними роботами. Дозволяє оцінити надійність доказової бази."}]$t32fq$::JSONB WHERE slug = 'semantic-scholar' AND lang = 'ua';
UPDATE tools SET choose_if = $t33ci$["✅ Вам потрібно швидко побудувати клієнтський портал, сайт або застосунок на основі Airtable або Google Sheets", "✅ Softr перетворює Airtable у повноцінний застосунок з аутентифікацією і дозволами за хвилини", "✅ Ідеально для membership-сайтів, клієнтських порталів і B2B SaaS-прототипів", "✅ Softr набагато простіший ніж Bubble — менше навчання і швидше запускається"]$t33ci$::JSONB, faq = $t33fq$[{"q": "Softr vs Webflow — яка різниця?", "a": "Softr будує застосунки і портали на основі баз даних (Airtable, Sheets). Webflow будує статичні маркетингові сайти і CMS. Softr для динамічних застосунків з даними; Webflow для дизайнерських маркетингових сайтів."}, {"q": "Softr безкоштовний?", "a": "Softr має безкоштовний план. Starter від $49/міс. Bubble має безкоштовний план; Starter від $32/міс."}, {"q": "Softr підтримує Airtable?", "a": "Так. Інтеграція Softr з Airtable — одна з найсильніших. Ви можете будувати застосунки де Airtable — база даних а Softr — фронтенд з аутентифікацією і дозволами."}, {"q": "Чи потрібен Airtable для Softr?", "a": "Ні. Softr також підтримує Google Sheets, HubSpot і Softr DB (власну базу даних). Але Airtable — найпопулярніше і найпотужніше джерело даних для Softr."}]$t33fq$::JSONB WHERE slug = 'softr' AND lang = 'ua';
UPDATE tools SET choose_if = $t34ci$["✅ Вам потрібно генерувати повноцінні пісні з вокалом, мелодією і словами з текстового опису", "✅ Suno створює музику різних жанрів — поп, рок, хіп-хоп, джаз — за кілька секунд", "✅ Ідеально для фонової музики, демо, джинглів і творчих проєктів без музичних навичок", "✅ Suno безкоштовний для базового використання з 50 піснями/день"]$t34ci$::JSONB, faq = $t34fq$[{"q": "Suno vs ElevenLabs — яка різниця?", "a": "Suno генерує музику — пісні з вокалом і мелодією. ElevenLabs генерує мовлення — реалістичні голоси для озвучення. Різні продукти для різних потреб."}, {"q": "Suno безкоштовний?", "a": "Suno має безкоштовний план з 50 пісень/день (не комерційне використання). Pro $8/міс — 500 пісень і комерційні права. ElevenLabs безкоштовний з обмеженнями; платні від $5/міс."}, {"q": "Чи можна використовувати Suno комерційно?", "a": "Безкоштовний план — некомерційне використання. Pro і Premier плани дають комерційні права. Перевіряйте актуальні умови використання на сайті Suno."}, {"q": "ElevenLabs підтримує українську мову?", "a": "Так. ElevenLabs підтримує синтез мовлення та клонування голосу українською мовою. Якість висока для читання тексту і озвучення."}]$t34fq$::JSONB WHERE slug = 'suno' AND lang = 'ua';
UPDATE tools SET choose_if = $t35ci$["✅ Вам потрібна платформа для дітей де навчання через вирішення складних головоломок і стратегій", "✅ Synthesis розроблений для обдарованих дітей і тих що шукають виклик — не стандартну програму", "✅ Захоплюючий ігровий підхід що розвиває критичне мислення і вирішення проблем", "✅ Synthesis Tutor — персональний ШІ-математичний тьютор для Synthesis-підходу"]$t35ci$::JSONB, faq = $t35fq$[{"q": "Synthesis vs Khan Academy — яка різниця?", "a": "Khan Academy — безкоштовна навчальна платформа з відео і вправами. Synthesis — платформа з головоломками і командними завданнями для розвитку мислення. Khan Academy для стандартної програми; Synthesis для розвитку нестандартного мислення."}, {"q": "Synthesis скільки коштує?", "a": "Synthesis від $35/міс. Khanmigo $44/рік або безкоштовно через партнерства зі школами. Khan Academy повністю безкоштовний."}, {"q": "Synthesis для якого віку?", "a": "Synthesis орієнтований на дітей 5-14 років. Khanmigo підходить для ширшого діапазону — від початкової школи до університету."}, {"q": "Khanmigo доступний в Україні?", "a": "Khanmigo доступний онлайн. Khan Academy має часткові переклади на українську мову. Перевіряйте доступність кількома мовами на khanacademy.org."}]$t35fq$::JSONB WHERE slug = 'synthesis' AND lang = 'ua';
UPDATE tools SET choose_if = $t36ci$["✅ Вам потрібна найпотужніша аналітична платформа для складного аналізу великих даних", "✅ Tableau AI (Einstein Copilot) дозволяє аналізувати дані природньою мовою", "✅ Tableau кращий для складних візуалізацій і enterprise аналітики", "✅ Потужніший для нестандартних розрахунків і великих датасетів"]$t36ci$::JSONB, faq = $t36fq$[{"q": "Looker Studio vs Power BI — яка різниця?", "a": "Looker Studio безкоштовний і відмінний для Google-екосистеми. Power BI потужніший для Microsoft-середовищ і enterprise аналітики. Обидва мають ШІ-функції. Для Google — Looker Studio; для Microsoft — Power BI."}, {"q": "Looker Studio безкоштовний?", "a": "Так. Looker Studio (раніше Data Studio) повністю безкоштовний. Tableau починається від $75/користувач/міс (Creator). Power BI безкоштовний для базового використання; Premium від $10/користувач/міс."}, {"q": "Tableau AI що вміє?", "a": "Tableau AI (Tableau Einstein) дозволяє ставити запитання до ваших даних природньою мовою і отримувати візуалізації. Також прогнозування трендів і виявлення аномалій автоматично."}, {"q": "Looker Studio для e-commerce?", "a": "Так. Looker Studio популярний для e-commerce аналітики: GA4, Google Ads, Search Console. Є безліч готових шаблонів для e-commerce дашбордів. Для інтеграції з Facebook Ads або іншими платформами потрібні сторонні конектори."}]$t36fq$::JSONB WHERE slug = 'tableau-ai' AND lang = 'ua';
UPDATE tools SET choose_if = $t37ci$["✅ Вам потрібен красивий маркетинговий сайт або лендінг з точним контролем дизайну", "✅ Webflow виробляє чистий HTML/CSS і дає дизайнерам повний контроль над зовнішнім виглядом", "✅ Webflow CMS і SEO-інструменти краще підходять для контент-сайтів і агентств", "✅ Краща продуктивність і SEO-оптимізація ніж у Bubble для публічних сайтів"]$t37ci$::JSONB, faq = $t37fq$[{"q": "Bubble vs Webflow — що обрати для стартапу?", "a": "Bubble для стартапів що будують SaaS або застосунки з бізнес-логікою і базами даних. Webflow для маркетингових сайтів і агентств. Для MVP з функціональністю — Bubble; для красивого сайту — Webflow."}, {"q": "Bubble безкоштовний?", "a": "Bubble має безкоштовний план для розробки. Starter від $32/міс. Webflow безкоштовний для дизайну; Starter від $14/міс."}, {"q": "Чи можна масштабувати Bubble-застосунок?", "a": "Так, Bubble масштабується. Великі застосунки з тисячами користувачів працюють на Bubble. Для дуже великого навантаження потрібні вищі плани і оптимізація запитів до бази даних."}, {"q": "Webflow vs WordPress — яка різниця?", "a": "Webflow — візуальний конструктор сайтів з чистим кодом. WordPress — CMS з тисячами плагінів і більшою гнучкістю контенту. Webflow для дизайнерів що хочуть контроль; WordPress для контент-важких сайтів з великою екосистемою."}]$t37fq$::JSONB WHERE slug = 'webflow' AND lang = 'ua';
UPDATE tools SET choose_if = $t38ci$["✅ Вам потрібен ШІ-тьютор що навчає з відео, PDF і статей через діалог", "✅ YouLearn перетворює будь-який контент на інтерактивний навчальний досвід з тестами і флешкартами", "✅ YouLearn активно навчає через перевірку знань — не просто відповідає на запитання", "✅ Ідеально для студентів що хочуть засвоїти матеріал а не лише прочитати його"]$t38ci$::JSONB, faq = $t38fq$[{"q": "YouLearn vs NotebookLM — що обрати для навчання?", "a": "YouLearn активніше навчає: тести, флешкарти і перевірка знань. NotebookLM пасивніший: відповідає на запитання і генерує подкасти. YouLearn для засвоєння; NotebookLM для дослідження і організації матеріалів."}, {"q": "YouLearn безкоштовний?", "a": "YouLearn має безкоштовний план з обмеженнями. Pro від $12/міс. NotebookLM повністю безкоштовний від Google."}, {"q": "YouLearn підтримує YouTube?", "a": "Так. YouLearn аналізує YouTube відео і перетворює їх на інтерактивні уроки з тестами і конспектами. Ідеально для навчання з онлайн-курсів і лекцій."}, {"q": "NotebookLM vs Obsidian для управління знаннями?", "a": "NotebookLM — ШІ для запитань до ваших документів. Obsidian — локальна система нотаток з посиланнями між ідеями. Різні інструменти: NotebookLM для аналізу джерел; Obsidian для побудови особистої бази знань."}]$t38fq$::JSONB WHERE slug = 'youlearn' AND lang = 'ua';
UPDATE tools SET choose_if = $t39ci$["✅ Вам потрібна автоматизація між різними застосунками з ШІ-логікою для прийняття рішень", "✅ Zapier AI будує автоматизації між тисячами застосунків з природньомовними інструкціями", "✅ AI Actions у Zapier дозволяють ШІ-кроки у складних робочих потоках", "✅ Не прив'язані до Notion — автоматизуйте будь-які комбінації SaaS-інструментів"]$t39ci$::JSONB, faq = $t39fq$[{"q": "Notion AI vs ChatGPT — що краще для нотаток?", "a": "Notion AI кращий якщо ви вже у Notion: він знає ваші документи і може з ними працювати. ChatGPT потужніший загально але не має доступу до ваших нотаток. Для Notion-команд — Notion AI; для загального ШІ — ChatGPT."}, {"q": "Notion AI безкоштовний?", "a": "Notion AI Plus — $16/міс/учасника (щорічно) або $20/міс щомісячно, додатково до базового Notion. Zapier має безкоштовний план; AI-функції у платних планах від $19,99/міс."}, {"q": "Zapier AI що це таке?", "a": "Zapier AI — набір ШІ-функцій у Zapier включно з AI Actions (природньомовні кроки у Zap), AI Chatbot (побудова чат-ботів) і Canvas (візуальний будівник автоматизацій з ШІ). Дозволяє будувати складніші автоматизації."}, {"q": "Notion AI може писати код?", "a": "Notion AI може писати базовий код і SQL. Але для серйозного кодування Cursor, GitHub Copilot або Claude Code значно потужніші. Notion AI краще для текстових завдань ніж для кодування."}]$t39fq$::JSONB WHERE slug = 'zapier-ai' AND lang = 'ua';
COMMIT;